// ANY multirotor: fly to a waypoint 15 m out and hold it, in gusty wind - with ONE controller for every craft.
// Nothing here names a motor. At init the script reads ctx.craft (each rotor's output, position about the centre
// of mass, spin and rated thrust) and builds the motor mixer from the geometry: a least-squares allocation of
// [lift, pitch moment, roll moment, yaw torque] onto however many rotors the craft has (quad, hex, lopsided penta...).
// Evolution then tunes the 9 gains of the cascade for that craft's mass, inertia and layout.
//   goal: (15, 8, 8) m from the spawn point (the craft's target sensor sits at (0, 10, 0))
function terms() { return ["height", "hold", "calm", "drift", "upright", "spin", "crash"]; }
var GOAL = { x: 15, y: 8, z: 8 };
function goal(i) { return { dx: i["target.dx"] + GOAL.x, dy: i["target.dy"] - 10 + GOAL.y, dz: i["target.dz"] + GOAL.z }; }

function reward(ctx) {
  const i = ctx.in, dt = ctx.dt, g = goal(i);
  const dh = Math.sqrt(g.dx * g.dx + g.dz * g.dz), d = Math.sqrt(dh * dh + g.dy * g.dy);
  const tilt = Math.min(Math.sqrt(i["att.pitch"] * i["att.pitch"] + i["att.roll"] * i["att.roll"]) / 90, 1);
  return {
    height: -Math.min(Math.abs(g.dy), 20) / 10 * dt,
    hold: d < 1.5 ? dt : 0,                                   // seconds within 1.5 m of the waypoint (headline)
    calm: -Math.min(Math.abs(i.vs) / 5, 1) * (d < 3 ? 1 : 0.2) * dt * 0.5,
    drift: -Math.min(dh / 20, 1) * dt,
    upright: -tilt * dt * 0.5,
    spin: -Math.min(Math.abs(i["rate.yaw"]) / 180, 1) * dt * 0.3,
  };
}
function failed(ctx) {
  const i = ctx.in;
  return ctx.state.crashed || Math.abs(i["att.pitch"]) > 80 || Math.abs(i["att.roll"]) > 80 || i.alt > 40;
}
function terminate(ctx) { return failed(ctx); }
function fitness(ctx) {
  const crash = failed(ctx) ? -1.5 * (ctx.info.duration - ctx.t) - 1 : 0;
  const s = ctx.sum;
  return { fitness: s.height + s.hold + s.calm + s.drift + s.upright + s.spin + crash, terms: { crash: crash } };
}

function genome(base) {
  const g = (name, lo, hi, init) => base.genes.push({ name: name, group: "script", min: lo, max: hi, initial: init, sigma: (hi - lo) / 10 });
  g("kAlt", 0, 1, 0.1);        // lift fraction of weight per m of height error
  g("kVs", 0, 1, 0.1);         // per m/s of climb rate
  g("kAltI", 0, 0.5, 0.02);    // per m*s (trims thrust-model error)
  g("kAtt", 0, 0.1, 0.01);     // moment (weight x arm units) per deg of attitude error
  g("kRate", 0, 0.03, 0.002);  // per deg/s of body rate
  g("kPos", 0, 5, 0.5);        // deg of lean per m of position error
  g("kVel", 0, 10, 1);         // deg of lean per m/s of ground speed
  g("kYaw", 0, 0.06, 0.005);   // yaw torque units per deg/s of yaw rate
  g("tilt", 10, 45, 25);       // lean limit, deg
  return base;
}

// --- auto-wiring: rotor geometry -> allocation matrix (pseudo-inverse), built once per episode
function wire(ctx) {
  const R = ctx.craft.rotors, n = R.length;
  if (n < 4) throw new Error("this controller needs 4+ rotors, craft has " + n);
  let L = 0; R.forEach(r => L += Math.sqrt(r.x * r.x + r.z * r.z) / n);
  // columns: lift (N), pitch (+x rotors raise the nose), roll (-z rotors raise the left side), yaw (spin +1 rotors yaw -rate)
  const B = [R.map(() => 1), R.map(r => r.x / L), R.map(r => -r.z / L), R.map(r => r.spin)];
  const M = [0, 1, 2, 3].map(a => [0, 1, 2, 3].map(b => B[a].reduce((s, v, k) => s + v * B[b][k], 0)));
  const Mi = inv4(M);
  // P = B^T (B B^T)^-1  (n x 4): rotor thrusts (N) for a wanted [lift N, pitch N, roll N, yaw N]
  const P = R.map((r, k) => [0, 1, 2, 3].map(c => [0, 1, 2, 3].reduce((s, a) => s + B[a][k] * Mi[a][c], 0)));
  return { R: R, P: P, W: ctx.craft.mass * 9.81 };
}
function inv4(m) {
  const n = 4, a = m.map((r, i) => r.concat([0, 1, 2, 3].map(j => (i === j ? 1 : 0))));
  for (let c = 0; c < n; c++) {
    let p = c; for (let r = c + 1; r < n; r++) if (Math.abs(a[r][c]) > Math.abs(a[p][c])) p = r;
    const t = a[c]; a[c] = a[p]; a[p] = t;
    const d = a[c][c] || 1e-9; for (let j = 0; j < 2 * n; j++) a[c][j] /= d;
    for (let r = 0; r < n; r++) if (r !== c) { const f = a[r][c]; for (let j = 0; j < 2 * n; j++) a[r][j] -= f * a[c][j]; }
  }
  return a.map(r => r.slice(n));
}

function control(ctx) {
  const G = ctx.genome, i = ctx.in, m = ctx.memory, dt = ctx.dt;
  if (!m.w) m.w = wire(ctx);
  const w = m.w, g = goal(i);
  const vx = m.pdx === undefined ? 0 : -(g.dx - m.pdx) / dt, vz = m.pdz === undefined ? 0 : -(g.dz - m.pdz) / dt;
  m.vx = m.vx === undefined ? 0 : m.vx + (vx - m.vx) * 0.3; m.vz = m.vz === undefined ? 0 : m.vz + (vz - m.vz) * 0.3;
  m.pdx = g.dx; m.pdz = g.dz;
  const lim = G.get("tilt"), kPos = G.get("kPos"), kVel = G.get("kVel");
  const pitchSp = clamp(-(kPos * g.dx - kVel * m.vx), -lim, lim);
  const rollSp = clamp(kPos * g.dz - kVel * m.vz, -lim, lim);
  const tilt = Math.min(Math.sqrt(i["att.pitch"] * i["att.pitch"] + i["att.roll"] * i["att.roll"]), 80) * Math.PI / 180;
  const ey = clamp(g.dy, -10, 10);
  m.ai = clamp((m.ai || 0) + ey * dt, -5, 5);
  const lift = w.W * (1 + G.get("kAlt") * ey - G.get("kVs") * i.vs + G.get("kAltI") * m.ai) / Math.max(Math.cos(tilt), 0.3);
  const kA = G.get("kAtt"), kR = G.get("kRate");
  const u = [lift,
    w.W * (kA * (pitchSp - i["att.pitch"]) - kR * i["rate.pitch"]),
    w.W * (kA * (rollSp - i["att.roll"]) - kR * i["rate.roll"]),
    -w.W * G.get("kYaw") * i["rate.yaw"]];
  for (let k = 0; k < w.R.length; k++) {
    const p = w.P[k];
    const T = p[0] * u[0] + p[1] * u[1] + p[2] * u[2] + p[3] * u[3];
    ctx.out[w.R[k].output] = Math.pow(clamp(T / w.R[k].thrust, 0, 1), 1.5);   // thrust fraction -> motor command
  }
}
